-- ============================================================================
-- CI seed data -- PostgreSQL dialect
-- ============================================================================
-- 镜像源:src/services/database/adapter/PgSQLAdapter.js
--   initGlobalSchema  L1435-1534(18 张全局表,public. 限定)
--   initUserSchema    L1275-1401 (22 张用户表,account_abc. 限定)
-- 同步义务:本文件 DDL 必须与 adapter 源码逐字一致(列名/类型/NOT NULL/
--   DEFAULT/主键/唯一约束/列顺序)。修改 adapter 建表语句时必须同步更新本文件。
-- 幂等策略:DDL 用 CREATE TABLE IF NOT EXISTS;DML 用
--   INSERT ... ON CONFLICT (该表完整主键列) DO NOTHING,整个文件可重复执行。
--   索引用 CREATE INDEX IF NOT EXISTS,名称与 adapter 完全一致。
-- 方言注意事项:
--   - 全局表显式 public. 限定,用户表 account_abc. 限定;用户表前先建 schema。
--   - 自增列为 BIGINT GENERATED BY DEFAULT AS IDENTITY,可显式插入 id。
--   - cookies/configs 的 key 非保留字,裸写。
--   - activity_bucket_cache_v2 的 json 列有 DEFAULT '[]'/'[]'/'{}',但按
--     镜像规则仍显式赋值;ascii 列仅填 ASCII 值。
--   - gamelog_event / gamelog_external 的 UNIQUE 约束不带前缀长度
--     (PG 的 TEXT 可直接建唯一索引),种子值均 < 100 字符。
--   - 9 个 CREATE INDEX IF NOT EXISTS:4 个用户表索引(镜像 L1350-1361)
--     + 5 个全局表索引(镜像 L1498-1512),名称与 adapter 完全一致。
--   - 末尾 setval 同步块:本文件全部显式插入 identity 主键 id,而 PG 的
--     GENERATED BY DEFAULT AS IDENTITY 不会随显式插入推进底层序列(MySQL
--     InnoDB 会自动抬升 auto_increment,PG 不会),故在全部 DML 之后对 17 张
--     identity PK 表执行 setval(pg_get_serial_sequence(...), MAX(id)),
--     确保后续无显式 id 的 INSERT 不会撞主键。该块同样幂等,可重复执行。
-- 章节:1. Global DDL -> 2. User DDL -> 3. Global DML -> 4. User DML -> 5. Identity sequence sync
-- 数据规划:22 行 global + 29 行 user(逐表行数见各表注释),满足 CI smoke 计数断言。
-- ============================================================================

-- ── 1. Global DDL(18 tables, schema public, mirrored from initGlobalSchema L1435-1534) ──

CREATE TABLE IF NOT EXISTS public.gamelog_location (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, location TEXT, world_id TEXT, world_name TEXT, time BIGINT, group_name TEXT, UNIQUE(created_at, location));
CREATE TABLE IF NOT EXISTS public.gamelog_join_leave (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, type TEXT, display_name TEXT, location TEXT, user_id TEXT, time BIGINT, UNIQUE(created_at, type, display_name));
CREATE TABLE IF NOT EXISTS public.gamelog_portal_spawn (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, display_name TEXT, location TEXT, user_id TEXT, instance_id TEXT, world_name TEXT, UNIQUE(created_at, display_name));
CREATE TABLE IF NOT EXISTS public.gamelog_video_play (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, video_url TEXT, video_name TEXT, video_id TEXT, location TEXT, display_name TEXT, user_id TEXT, UNIQUE(created_at, video_url));
CREATE TABLE IF NOT EXISTS public.gamelog_resource_load (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, resource_url TEXT, resource_type TEXT, location TEXT, UNIQUE(created_at, resource_url));
CREATE TABLE IF NOT EXISTS public.gamelog_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, data TEXT, UNIQUE(created_at, data));
CREATE TABLE IF NOT EXISTS public.gamelog_external (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, message TEXT, display_name TEXT, user_id TEXT, location TEXT, UNIQUE(created_at, message));
CREATE TABLE IF NOT EXISTS public.cache_avatar (id TEXT PRIMARY KEY, added_at TEXT, author_id TEXT, author_name TEXT, created_at TEXT, description TEXT, image_url TEXT, name TEXT, release_status TEXT, thumbnail_image_url TEXT, updated_at TEXT, version BIGINT);
CREATE TABLE IF NOT EXISTS public.cache_world (id TEXT PRIMARY KEY, added_at TEXT, author_id TEXT, author_name TEXT, created_at TEXT, description TEXT, image_url TEXT, name TEXT, release_status TEXT, thumbnail_image_url TEXT, updated_at TEXT, version BIGINT);
CREATE TABLE IF NOT EXISTS public.favorite_world (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, world_id TEXT, group_name TEXT);
CREATE TABLE IF NOT EXISTS public.favorite_avatar (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, avatar_id TEXT, group_name TEXT);
CREATE TABLE IF NOT EXISTS public.favorite_friend (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, user_id TEXT, group_name TEXT);
CREATE TABLE IF NOT EXISTS public.memos (user_id TEXT PRIMARY KEY, edited_at TEXT, memo TEXT);
CREATE TABLE IF NOT EXISTS public.world_memos (world_id TEXT PRIMARY KEY, edited_at TEXT, memo TEXT);
CREATE TABLE IF NOT EXISTS public.avatar_memos (avatar_id TEXT PRIMARY KEY, edited_at TEXT, memo TEXT);
CREATE TABLE IF NOT EXISTS public.avatar_tags (avatar_id TEXT NOT NULL, tag TEXT NOT NULL, color TEXT, PRIMARY KEY (avatar_id, tag));
CREATE TABLE IF NOT EXISTS public.cookies (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS public.configs (key TEXT PRIMARY KEY, value TEXT);

-- Global indexes(5, mirrored from initGlobalSchema L1498-1512)
CREATE INDEX IF NOT EXISTS gamelog_location_created_at_idx ON public.gamelog_location (created_at);
CREATE INDEX IF NOT EXISTS idx_gamelog_location_world_created ON public.gamelog_location (world_id, created_at);
CREATE INDEX IF NOT EXISTS idx_gamelog_jl_location ON public.gamelog_join_leave (location);
CREATE INDEX IF NOT EXISTS idx_gamelog_jl_user_created ON public.gamelog_join_leave (user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_gamelog_jl_display_created ON public.gamelog_join_leave (display_name, created_at);

-- ── 2. User DDL(22 tables, schema account_abc, mirrored from initUserSchema L1275-1401) ──

CREATE SCHEMA IF NOT EXISTS account_abc;

CREATE TABLE IF NOT EXISTS account_abc.feed_gps (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, user_id TEXT, display_name TEXT, location TEXT, world_name TEXT, previous_location TEXT, time BIGINT, group_name TEXT);
CREATE TABLE IF NOT EXISTS account_abc.feed_status (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, user_id TEXT, display_name TEXT, status TEXT, status_description TEXT, previous_status TEXT, previous_status_description TEXT);
CREATE TABLE IF NOT EXISTS account_abc.feed_bio (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, user_id TEXT, display_name TEXT, bio TEXT, previous_bio TEXT);
CREATE TABLE IF NOT EXISTS account_abc.feed_avatar (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, user_id TEXT, display_name TEXT, owner_id TEXT, avatar_name TEXT, current_avatar_image_url TEXT, current_avatar_thumbnail_image_url TEXT, previous_current_avatar_image_url TEXT, previous_current_avatar_thumbnail_image_url TEXT);
CREATE TABLE IF NOT EXISTS account_abc.feed_online_offline (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, user_id TEXT, display_name TEXT, type TEXT, location TEXT, world_name TEXT, time BIGINT, group_name TEXT);
CREATE TABLE IF NOT EXISTS account_abc.activity_sync_state_v2 (user_id TEXT PRIMARY KEY, updated_at TEXT NOT NULL DEFAULT '', is_self BIGINT NOT NULL DEFAULT 0, source_last_created_at TEXT NOT NULL DEFAULT '', pending_session_start_at BIGINT, cached_range_days BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS account_abc.activity_sessions_v2 (session_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id TEXT NOT NULL, start_at BIGINT NOT NULL, end_at BIGINT NOT NULL, is_open_tail BIGINT NOT NULL DEFAULT 0, source_revision TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS account_abc.activity_bucket_cache_v2 (user_id TEXT NOT NULL, target_user_id TEXT NOT NULL DEFAULT '', range_days BIGINT NOT NULL, view_kind TEXT NOT NULL, exclude_key TEXT NOT NULL DEFAULT '', bucket_version BIGINT NOT NULL DEFAULT 1, raw_buckets_json TEXT NOT NULL DEFAULT '[]', normalized_buckets_json TEXT NOT NULL DEFAULT '[]', built_from_cursor TEXT NOT NULL DEFAULT '', summary_json TEXT NOT NULL DEFAULT '{}', built_at TEXT NOT NULL DEFAULT '', PRIMARY KEY (user_id, target_user_id, range_days, view_kind, exclude_key));
CREATE TABLE IF NOT EXISTS account_abc.friend_log_current (user_id TEXT PRIMARY KEY, display_name TEXT, trust_level TEXT, friend_number BIGINT);
CREATE TABLE IF NOT EXISTS account_abc.friend_log_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at TEXT, type TEXT, user_id TEXT, display_name TEXT, previous_display_name TEXT, trust_level TEXT, previous_trust_level TEXT, friend_number BIGINT);
CREATE TABLE IF NOT EXISTS account_abc.notifications (id TEXT PRIMARY KEY, created_at TEXT, type TEXT, sender_user_id TEXT, sender_username TEXT, receiver_user_id TEXT, message TEXT, world_id TEXT, world_name TEXT, image_url TEXT, invite_message TEXT, request_message TEXT, response_message TEXT, expired BIGINT);
CREATE TABLE IF NOT EXISTS account_abc.notifications_v2 (id TEXT PRIMARY KEY, created_at TEXT, updated_at TEXT, expires_at TEXT, type TEXT, link TEXT, link_text TEXT, message TEXT, title TEXT, image_url TEXT, seen BIGINT, sender_user_id TEXT, sender_username TEXT, data TEXT, responses TEXT, details TEXT);
CREATE TABLE IF NOT EXISTS account_abc.moderation (user_id TEXT PRIMARY KEY, updated_at TEXT, display_name TEXT, block BIGINT, mute BIGINT);
CREATE TABLE IF NOT EXISTS account_abc.avatar_history (avatar_id TEXT PRIMARY KEY, created_at TEXT, time BIGINT);
CREATE TABLE IF NOT EXISTS account_abc.notes (user_id TEXT PRIMARY KEY, display_name TEXT, note TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS account_abc.mutual_graph_friends (friend_id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS account_abc.mutual_graph_links (friend_id TEXT NOT NULL, mutual_id TEXT NOT NULL, PRIMARY KEY(friend_id, mutual_id));
CREATE TABLE IF NOT EXISTS account_abc.mutual_graph_links_old (friend_id TEXT NOT NULL, mutual_id TEXT NOT NULL, date TEXT NOT NULL, PRIMARY KEY(friend_id, mutual_id));
CREATE TABLE IF NOT EXISTS account_abc.mutual_graph_friends_old (friend_id TEXT PRIMARY KEY, last_updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS account_abc.mutual_graph_meta (friend_id TEXT PRIMARY KEY, last_fetched_at TEXT, opted_out BIGINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS account_abc.tracked_nonfriends (user_id TEXT PRIMARY KEY, display_name TEXT, added_at TEXT);
CREATE TABLE IF NOT EXISTS account_abc.manual_relations_MANUEL (user_id_a TEXT NOT NULL, user_id_b TEXT NOT NULL, relation_type TEXT NOT NULL DEFAULT 'friend', added_at TEXT, PRIMARY KEY(user_id_a, user_id_b));

-- User indexes(4, mirrored from initUserSchema L1350-1361)
CREATE INDEX IF NOT EXISTS feed_online_offline_user_created_idx ON account_abc.feed_online_offline (user_id, created_at);
CREATE INDEX IF NOT EXISTS activity_sessions_v2_user_start_idx ON account_abc.activity_sessions_v2 (user_id, start_at);
CREATE INDEX IF NOT EXISTS activity_sessions_v2_user_end_idx ON account_abc.activity_sessions_v2 (user_id, end_at);
CREATE INDEX IF NOT EXISTS friend_log_history_user_id_idx ON account_abc.friend_log_history (user_id);

