-- ── 5. Identity sequence sync(17 identity PK tables) ──
-- PG 的 GENERATED BY DEFAULT AS IDENTITY 序列不随显式 id 插入推进,这里把
-- 每张表的序列抬升到当前 MAX 值,保证导入后无显式 id 的 INSERT 不会拿到
-- 已占用的 id。表名单与上方 DDL 逐字一致;TEXT 主键/复合主键表无需处理。
-- (注意 activity_sessions_v2 的 identity 列名为 session_id,非 id。)

SELECT setval(pg_get_serial_sequence('public.gamelog_location','id'), COALESCE(MAX(id),1)) FROM public.gamelog_location;
